#!/usr/bin/env bash
set -euo pipefail
# Starfare design-doc commit: transport model (design-ahead) + resolve the instant-SELL/fuel loose end.
# Run from repo root: gitserver@gitserver:/mnt/git-server/starfare  (does NOT push)
test -f docs/design.md || { echo "!! run me from the starfare repo root"; exit 1; }

python3 - <<'PYEOF'
import base64
def d(b): return base64.b64decode(b).decode("utf-8")
# --- new file ---
open("docs/transport-model.md","w",encoding="utf-8").write(d(""))
# --- design.md edits (fail-loud) ---
p="docs/design.md"; s=open(p,encoding="utf-8").read()
oldA=d(""); newA=d("").rstrip("\n")
assert s.count(oldA)==1, f"design.md A anchor count={s.count(oldA)} (expected 1)"
s=s.replace(oldA,newA,1)
oldB="## 6. Logistics: Travel Time, Vehicles, and Risk in Transit\n"; newB=d("").rstrip("\n")+"\n"
assert s.count(oldB)==1, f"design.md B anchor count={s.count(oldB)} (expected 1)"
s=s.replace(oldB,newB,1)
oldC=d("Q3J1Y2lhbGx5LCAqKmh1bWFuIHBpcmFjeSBpcyBhbiBlbWVyZ2VudCBwbGF5c3R5bGUqKiB1c2luZyB0aGUgc2FtZSBtZWNoYW5pY3Mg4oCUIGJ1dCBhdHRyaWJ1dGFibGUsIGFuZCB0aGVyZWZvcmUgc3ViamVjdCB0byBsZWdhbGl0eSBjb25zZXF1ZW5jZXMsIGdpdmluZyBhIGNsZWFuIGxpbmUgZm9yIHdoZW4gdGhlIHBvbGl0aWNhbCBtYWNoaW5lcnkgZW5nYWdlcy4="); newC=d("").rstrip("\n")
assert s.count(oldC)==1, f"design.md C anchor count={s.count(oldC)} (expected 1)"
s=s.replace(oldC,newC,1)
assert s.count("RESOLVED IN DIRECTION")==1 and "Flagged, not resolved" not in s
open(p,"w",encoding="utf-8").write(s)
print("design.md: loose end resolved, transport-model pointer, piracy Phase-1 note")
print("docs/transport-model.md: created")
PYEOF

git add docs/transport-model.md docs/design.md
git commit -m "docs: transport model (design-ahead) + resolve the instant-SELL / fuel loose end

Capture the transport subsystem worked out on paper across the BUY-engine thread:
the leg primitive (Euclidean length, departure/arrival ticks, position interpolation,
position->hex crossover), gate-anchored graph routing, the toll network (guilds own
gates, charged per gate, <=10/<=20 hex, 2x buff = the unified secured-edge bonus),
per-craft speed table, legProgress for the map/transport-tab overlay, Phase-1
storyteller-only piracy with cargo-loss/damage/delay outcomes, and the route planner
(cost/time/risk, save + re-validate). New docs/transport-model.md is the source of
truth; the Syndicate tier is built, the guild tier is Phase 4.

Resolve the instant-SELL 'goods move free' tension flagged with the BUY commit: doing
business with the Syndicate spends a reputation-replenished FUEL-CREDIT allowance --
the Phase-1 lightweight stand-in for section 8's allocation-as-purchasing-power -- so
fuel still gates Syndicate trade with no physical haul. Full deuterium machinery not
built; its relationship to fuel-credits left as the open ruling. Also record the
Phase-1 piracy simplification (storyteller-only) against section 10."

echo; echo "Done. Review: git show --stat HEAD ; then: git push origin main"
